# Generated by Claude (Claude Code).
"""PC1 vs PC2 of the cubic model's 32 features in one scatter: blue/green/red per true peak count,
shades per pattern, points drawn in random order. Reads the npz written by pca_features.py.
Usage: python pca_single.py <project dir> <npz> <out png>"""
import sys
import numpy as np
from matplotlib import rc_context
from matplotlib.figure import Figure
from matplotlib.lines import Line2D
sys.path.insert(0, sys.argv[1])
from plot import AXIS, GRIDLINE, RC, SURFACE, TEXT_MUTED, TEXT_PRIMARY, TEXT_SECONDARY  # noqa: E402

d = np.load(sys.argv[2], allow_pickle=True)
P, pats, var = d["P"], d["patterns"], d["var"]
SHADES = {  # class 0: blues, 1: greens, 2: reds; dark to light within a class
    "": "#1f3fbf", "V": "#6f8fff",
    "P": "#0b6b1f", "VP": "#1f9f3a", "PV": "#4cc35c", "VPV": "#93df8f",
    "PVP": "#8b0000", "VPVP": "#c81e1e", "PVPV": "#f05050", "VPVPV": "#ff9c8c",
}
order = np.random.default_rng(0).permutation(len(P))
colors = np.array([SHADES[p] for p in pats])[order]
with rc_context(RC):
    fig = Figure(figsize=(11, 8), dpi=160, facecolor=SURFACE)
    ax = fig.add_subplot()
    ax.set_facecolor(SURFACE)
    ax.scatter(P[order, 0], P[order, 1], s=1.4, c=colors, linewidths=0, alpha=0.8, rasterized=True)
    ax.set_aspect("equal", adjustable="datalim")
    ax.set_xlabel(f"PC1 ({100 * var[0]:.1f}% of the variance)", color=TEXT_SECONDARY)
    ax.set_ylabel(f"PC2 ({100 * var[1]:.1f}% of the variance)", color=TEXT_SECONDARY)
    ax.grid(color=GRIDLINE, linewidth=1)
    ax.set_axisbelow(True)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        ax.spines[side].set_color(AXIS)
    ax.tick_params(colors=AXIS, labelcolor=TEXT_MUTED, length=0, pad=6)
    handles = []
    for cls, name in ((0, "0 peaks"), (1, "1 peak"), (2, "2 peaks")):
        handles.append(Line2D([], [], linestyle="none", label=name))  # group heading
        for p, col in SHADES.items():
            if p.count("P") == cls:
                handles.append(Line2D([], [], marker="o", linestyle="none", markersize=7, color=col,
                                      label=f"  {p or '(none)'}  ({int(np.sum(pats == p)):,})"))
    leg = ax.legend(handles=handles, loc="upper left", bbox_to_anchor=(1.01, 1.0), frameon=False,
                    handletextpad=0.4, borderaxespad=0)
    for text, h in zip(leg.get_texts(), handles):
        text.set_color(TEXT_PRIMARY if h.get_marker() in (None, "None", "") else TEXT_SECONDARY)
        if h.get_marker() in (None, "None", ""):
            text.set_fontweight("semibold")
    fig.suptitle(f"PCA of the 32 features of the cubic-warp model ({d['title_model']})", x=0.08, y=0.965, ha="left", fontsize=13,
                 fontweight="semibold", color=TEXT_PRIMARY)
    fig.text(0.08, 0.925, "51,200 test functions (seed 12345, cubic warp, minimum knot distance 0.05) · run "
             f"{d['run']} · colour: true peak count, shade: pattern · random drawing order",
             ha="left", fontsize=9, color=TEXT_SECONDARY)
    fig.subplots_adjust(left=0.08, right=0.8, top=0.88, bottom=0.08)
    fig.savefig(sys.argv[3], facecolor=SURFACE, bbox_inches="tight", pad_inches=0.25)
print("saved", sys.argv[3])
